# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.errors import ProjectError
from rosterkit.models import Student

def _require_emails(students: List[Student]) -> None:
    for pupil in students:
        if not pupil.email:
            raise ProjectError(
                f"no email for {pupil.display_name}"
            )

def _line(cells, widths) -> str:
    pairs = zip(cells, widths)
    padded = [text.ljust(wide) for text, wide in pairs]
    return "  ".join(padded).rstrip()

def _cells(students: List[Student]) -> list:
    ordered = sorted(
        students, key=lambda pupil: pupil.display_name
    )
    return [
        (pupil.display_name, pupil.section, pupil.email)
        for pupil in ordered
    ]

# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Aligned name, section, email rows sorted by name."""
    if not students:
        raise ProjectError("no students to list")
    _require_emails(students)
    cells = _cells(students)
    widths = [max(map(len, left)) for left in zip(*cells)]
    return [_line(row, widths) for row in cells]

after.tests/test_contacts.py:
# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student

def _pupil(last, first, email="x@example.org"):
    return Student("1", last, first, "A", email)

def _sample_rows():
    return contact_rows([
        _pupil("Young", "Zed", "z@example.org"),
        _pupil("Abbott", "Amy", "a@example.org")
    ])

class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        want = [
            "Abbott, Amy  A  a@example.org",
            "Young, Zed   A  z@example.org"
        ]
        self.assertEqual(_sample_rows(), want)

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([_pupil("Young", "Zed", None)])
        self.assertIn("Young, Zed", str(caught.exception))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
